<script lang="ts">
	import * as Tabs from '#lib/components/ui/tabs/index.js';
	import StockGroups from './stock-groups.svelte';
	import type { PortfolioState } from '#lib/logic/portfolio-state.js';
	import type { Money } from '#lib/api/contracts.js';

	let { portfolio }: { portfolio: PortfolioState } = $props();
	const number = new Intl.NumberFormat('ru-RU', { maximumFractionDigits: 20 });
	const rub = new Intl.NumberFormat('ru-RU', { style: 'currency', currency: 'RUB', maximumFractionDigits: 2 });
	const percent = new Intl.NumberFormat('ru-RU', { style: 'unit', unit: 'percent', maximumFractionDigits: 2 });
	const value = (n: number | null | undefined) => n == null || !Number.isFinite(n) ? 'Нет данных' : rub.format(n);
	const share = (n: number | null | undefined) => n == null || !Number.isFinite(n) ? 'Нет данных' : percent.format(n);
	const money = (m: Money | null) => !m || !Number.isFinite(m.price) ? 'Нет данных' : `${number.format(m.price)} ${m.currency}`;
	const profileName = $derived(portfolio.data.profiles.find(profile => profile.default)?.name ?? '');
</script>

