	<Tabs.Content value="cards"><section aria-labelledby="live-cards-heading" class="space-y-5"><h2 id="live-cards-heading" class="text-lg font-semibold">Кредитные карты</h2><ul class="grid gap-3 sm:grid-cols-2">{#each portfolio.data.personal_assets.credit_cards as card (card.id)}<li class="min-w-0 rounded-xl border border-border bg-card p-4"><h3 class="break-words font-medium">{card.name}</h3><dl class="mt-3 grid grid-cols-2 gap-3 [&>div]:min-w-0 [&_dd]:wrap-anywhere"><div><dt class="text-xs text-muted-foreground">Банк</dt><dd class="text-sm">{card.bank_name}</dd></div><div><dt class="text-xs text-muted-foreground">Лимит</dt><dd class="text-sm">{value(card.overall_limit_rub)}</dd></div><div><dt class="text-xs text-muted-foreground">Обязательный платёж</dt><dd class="text-sm">{value(card.mandatory_payment_amount_rub)}</dd></div><div><dt class="text-xs text-muted-foreground">Дата платежа</dt><dd class="text-sm">{card.mandatory_payment_date || 'Нет данных'}</dd></div></dl></li>{:else}<li class="text-sm text-muted-foreground">Кредитных карт пока нет.</li>{/each}</ul></section></Tabs.Content>
